package com.civic.controller; import com.civic.dto.*; import com.civic.entity.*; import com.civic.repository.*; import com.civic.enums.PetitionStatus; import lombok.RequiredArgsConstructor; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/petitions") @RequiredArgsConstructor public class PetitionResponseController {private final PetitionRepository petitions;private final PetitionResponseLogRepository logs;private final UserRepository users;
 @PostMapping("/{id}/responses") @PreAuthorize("hasRole('OFFICIAL')") public PetitionOfficialResponse create(@PathVariable Long id,@RequestBody PetitionOfficialResponseRequest r){User u=me();Petition p=petitions.findById(id).orElseThrow(()->new RuntimeException("Petition not found"));access(p,u);if((r.getComment()==null||r.getComment().isBlank())&&r.getStatus()==null)throw new RuntimeException("Comment or status is required");if(r.getStatus()!=null)p.setStatus(r.getStatus());petitions.save(p);PetitionResponseLog x=logs.save(PetitionResponseLog.builder().petition(p).official(u).comment(r.getComment()).status(r.getStatus()).build());return map(x);}
 @GetMapping("/{id}/responses") public List<PetitionOfficialResponse> all(@PathVariable Long id){Petition p=petitions.findById(id).orElseThrow(()->new RuntimeException("Petition not found"));return logs.findByPetitionOrderByCreatedAtAsc(p).stream().map(this::map).toList();}
 private void access(Petition p,User u){if(u.getRole()==Role.SUPER_ADMIN)return;if(u.getDepartment()==null||p.getDepartment()==null||!u.getDepartment().equalsIgnoreCase(p.getDepartment()))throw new RuntimeException("You are not authorized for this department");}
 private User me(){return users.findByEmail(org.springframework.security.core.context.SecurityContextHolder.getContext().getAuthentication().getName()).orElseThrow(()->new RuntimeException("User not found"));}
 private PetitionOfficialResponse map(PetitionResponseLog x){return PetitionOfficialResponse.builder().id(x.getId()).petitionId(x.getPetition().getId()).officialId(x.getOfficial().getId()).officialName(x.getOfficial().getName()).officialEmail(x.getOfficial().getEmail()).comment(x.getComment()).status(x.getStatus()).createdAt(x.getCreatedAt()).build();}
}
